    support_us: {
      title: "Support Us",
      accent_label: "Fueling the exploration",
      section_title: "Support Our Journey",
      description_1: "Shotrip is maintained by a single engineer. Because we operate entirely on self-funding, we face significant challenges from rising fuel costs and the time constraints of balancing a professional career with field research.",
      description_2_1: "Support through",
      description_2_2: "helps us overcome these barriers, ensuring we can continue to deliver high-frequency, fresh, and authentic content from the field.",
      challenges_section_title: "The Challenges",
      challenges_section_sub_title_1: "Time Constraints",
      challenges_section_desc_1: "Managing high-quality media while working as an engineer requires significant resources to maintain the pace of updates.",
      challenges_section_sub_title_2: "Rising Logistics Costs",
      challenges_section_desc_2: "Increasing fuel prices directly impact our ability to reach remote areas. We rely 100% on self-funding for all field research.",
      challenges_section_sub_title_3: "Information Freshness",
      challenges_section_desc_3: "To provide \"real\" insights, frequent on-site visits are essential. Stale information helps no one in the world of travel.",
      challenges_section_sub_title_4: "Self-Funded Foundation",
      challenges_section_desc_4: "We operate primarily on self-funding to maintain our core perspective. While we remain open to sponsorships that align with our values, this foundation ensures our content always stays true to the real experience.",
      main_support_section_title: "Ways to Fuel Shotrip",
      main_support_section_desc_1: "By supporting us through",
      main_support_section_desc_2: ", you help us overcome these constraints and deliver better content, faster.",
      main_support_section_sub_title_1: "Small Support",
      main_support_section_sub_desc_1: "A simple way to contribute to our daily operation and server costs. Every cup of coffee keeps the engineering and writing going.",
      main_support_section_sub_title_2: "Research Request Ticket",
      main_support_section_sub_desc_2: "Request a specific region for us to explore. We will visit the location, gather the latest data, and report back through direct feedback, blog posts, or YouTube.",
      main_support_section_link_1: "Buy a Coffee",
      main_support_section_link_2: "Get a Ticket",
      main_support_section_parts_1: "Special",
      main_support_section_parts_2: "Direct & Public Reporting",
      closing_section: "Your support transforms \"interest\" into \"action.\" By funding our movements, you enable us to uncover the hidden truths of Japan's landscapes that remain invisible from behind a screen. Thank you for empowering our exploration.",
    },
    about_us: {
      title: "About Us",
      h1_1: "Redefining Travel in Japan",
      h1_2: "For a Sustainable, ",
      h1_3: "Authentic Future",
      description: "Shotrip is an independent media and technology project dedicated to resolving overtourism by connecting travelers with Japan's undiscovered gems.",
      philosophy_section_title: "\"Find Your Own Favorites\"",
      philosophy_section_desc_1: "In an era of viral social media trends, popular spots are often consumed by mass crowds. Shotrip encourages a different approach: discovering places that personally resonate with you.",
      philosophy_section_desc_2: "Our mission is to help travelers find a &quot;there&quot; so special they’ll want to tell their closest friends, \"You must go there\"—experiences that remain as cherished memories long after the trip ends.",
      philosophy_section_side_desc: "By highlighting Japan's 47 prefectures and hidden gems beyond the \"Golden Route,\" we aim to redistribute tourism and preserve the tranquility of local life.",
      system_section_title: "The Technology",
      system_section_sub_title_1: "Geographical Expertise,",
      system_section_sub_title_2: "Transplanted into AI.",
      system_section_desc: "ShotripLens is a proprietary AI concierge built by a single developer who has explored Japan’s entire rail network and every prefecture. This system translates years of geographical expertise and cultural understanding into a digital partner that supports your journey 24/7.",
      system_section_card: "47 prefectures explored / Full-stack engineering",
      system_section_commitment_title: "Our Commitments",
      system_section_commitment_sub_title_1: "Privacy First",
      system_section_commitment_desc_1: "Cookie-free operation. We use tech to empower travelers, not to track them.",
      system_section_commitment_sub_title_2: "Local Harmony",
      system_section_commitment_desc_2: "Prioritizing the peace of residents by encouraging the dispersion of crowds.",
      future_vision_section_title: "Future Vision",
      future_vision_section_sub_title: "Becoming the Standard for Sustainable Travel.",
      future_vision_section_desc: "Shotrip aims to bridge the gap between AI, local governments, and creators to foster a healthier tourism ecosystem. We are building more than a website; we are building a global community that values authenticity over popularity.",
      founder_notes: "\"Shotrip is the result of my lifelong passion for Japan and my frustration with the loss of its quiet beauty. It is a solo-engineered endeavor, built with an distinctive perspective, designed to share the true Japan with the world.\"",
    },
