        kyushu: "Une île volcanique passionnée, réputée pour ses ramen incroyables, ses villes thermales luxuriantes et ses cités portuaires historiques.",
        okinawa: "Le paradis tropical du Japon, offrant des eaux turquoise cristallines, un héritage Ryukyu unique et une ambiance insulaire décontractée."
