            2: "Au lieu de réserver dans des stations d'hiver surpeuplées et hautement commercialisées, adoptez le climat saisonnier dans des espaces gérés par la communauté et sur les pistes municipales ordinaires. S'engager dans les activités hivernales quotidiennes aux côtés des résidents permet de apprécier de manière intime et sereine la légendaire culture de la neige de l'île."
