            2: "Entrez au cœur tranquille de la fabrication en visitant les sites de production et les ateliers indépendants disséminés dans la région. Ces visites modestes mettent en valeur le véritable esprit de précision et d'innovation locale, vous permettant d'apprécier l'industrie authentique sans aucun battage touristique."
