            2: "Éloignez-vous des ruelles touristiques illuminées au néon et explorez les cultures culinaires authentiques qui prospèrent dans les quartiers résidentiels ordinaires. Dîner dans de humbles devantures de magasins et des restaurants locaux révèle le véritable cœur de l'hospitalité régionale et des saveurs profondément durables et honnêtes."
