            2: "Découvrez l'héritage durable des textiles et des matériaux locaux en vous promenant dans des districts de fabrication indépendants. S'engager directement avec les tisserands et les artisans teinturiers locaux offre une expérience consciente et durable qui célèbre la véritable slow fashion."
