            2: "La riche énergie volcanique de l'île est partout, mais la meilleure façon de l'expérimenter est d'éviter les grands centres de villégiature. S'installer dans les communautés de montagne baignées de vapeur permet une connexion profondément relaxante et privée avec la chaleur naturelle de la terre."
