        detail: "La cuisine japonaise, ou 'Washoku', est inscrite au patrimoine culturel immatériel de l'UNESCO. Il ne s'agit pas seulement de sushis ; c'est une exploration des ingrédients de saison et des spécialités régionales. Que vous dîniez dans un restaurant étoilé Michelin ou que vous preniez un ramen rapide, la qualité et la présentation sont exceptionnelles.",
