        detail: "La société japonaise repose sur le respect mutuel et l'Omotenashi (hospitalité). Bien que les locaux soient indulgents envers les touristes, suivre les règles sociales de base vous vaudra un grand respect. Être attentif à son environnement, notamment au bruit et à l'espace public, est la clé pour s'intégrer et profiter de son séjour.",
