      section_title: "Soutenez notre voyage",
      description_1: "Shotrip est maintenu par un seul ingénieur. Comme nous fonctionnons entièrement sur fonds propres, nous sommes confrontés à des défis importants liés à l'augmentation des coûts du carburant et aux contraintes de temps pour concilier carrière professionnelle et recherche sur le terrain.",
      description_2_1: "Votre soutien via",
      description_2_2: "nous aide à surmonter ces barrières, nous permettant de continuer à fournir un contenu frais, authentique et fréquent directement depuis le terrain.",
      challenges_section_title: "Les Défis",
      challenges_section_sub_title_1: "Contraintes de temps",
      challenges_section_desc_1: "Gérer un média de haute qualité tout en travaillant comme ingénieur demande des ressources considérables pour maintenir le rythme des mises à jour.",
      challenges_section_sub_title_2: "Coûts logistiques en hausse",
      challenges_section_desc_2: "L'augmentation des prix du carburant impacte directement notre capacité à atteindre les zones reculées. Nous dépendons à 100 % de l'autofinancement.",
      challenges_section_sub_title_3: "Fraîcheur de l'information",
      challenges_section_desc_3: "Pour fournir des perspectives réelles, des visites fréquentes sur place sont essentielles. Une information obsolète n'aide personne dans le monde du voyage.",
      challenges_section_sub_title_4: "Fondation auto-financée",
      challenges_section_desc_4: "Nous fonctionnons principalement sur fonds propres pour préserver notre perspective unique. Cela garantit que notre contenu reste fidèle à l'expérience réelle.",
      main_support_section_title: "Comment soutenir Shotrip",
      main_support_section_desc_1: "En nous soutenant via",
      main_support_section_desc_2: ", vous nous aidez à surmonter ces contraintes et à livrer un meilleur contenu, plus rapidement.",
      main_support_section_sub_title_1: "Petit soutien",
      main_support_section_sub_desc_1: "Un moyen simple de contribuer à nos frais de fonctionnement et de serveur. Chaque tasse de café soutient l'ingénierie et la rédaction.",
      main_support_section_sub_title_2: "Ticket de demande de recherche",
      main_support_section_sub_desc_2: "Demandez une région spécifique à explorer. Nous visiterons le lieu, recueillerons les données les plus récentes et ferons un rapport via blog ou YouTube.",
      main_support_section_link_1: "Offrir un café",
      main_support_section_link_2: "Prendre un ticket",
      main_support_section_parts_1: "Spécial",
      main_support_section_parts_2: "Rapport direct et public",
      closing_section: "Votre soutien transforme l'intérêt en action. En finançant nos déplacements, vous nous permettez de révéler les vérités cachées des paysages japonais qui restent invisibles derrière un écran. Merci de soutenir notre exploration.",
