      system_section_desc: "ShotripLens est un concierge IA exclusif conçu par un développeur unique ayant exploré l'intégralité du réseau ferroviaire et chaque préfecture du Japon. Ce système traduit des années d'expertise géographique et de compréhension culturelle en un partenaire numérique qui vous accompagne 24h/24 et 7j/7.",
