      future_vision_section_title: "Vision d'avenir",
      future_vision_section_sub_title: "Devenir la référence du voyage durable.",
      future_vision_section_desc: "Shotrip aspire à combler le fossé entre l'IA, les gouvernements locaux et les créateurs pour favoriser un écosystème touristique plus sain. Nous construisons plus qu'un site web ; nous bâtissons une communauté mondiale qui valorise l'authenticité plutôt que la popularité.",
      founder_notes: "« Shotrip est le résultat de ma passion de toujours pour le Japon et de ma frustration face à la perte de sa beauté sereine. C'est une entreprise en solo, conçue avec une perspective distinctive pour partager le vrai Japon avec le monde. »",
