            2: "Anstatt überlaufene historische Hotspots zu besuchen, schlendern Sie durch die normalen Straßen und älteren Viertel der Region. Das Entdecken gut erhaltener, alltäglicher traditioneller Gebäude in diesen ruhigen Gegenden bietet einen gelassenen, von Menschenmassen freien Einblick in das lebendige Erbe der Region."
