            2: "Überspringen Sie die überfüllten Fischmärkte der Stadt und genießen Sie den frischen Fang in lokalen Tavernen in der Nähe von ganz normalen Fischerdocks. Dort zu essen, wo die Einheimischen essen, stellt sicher, dass Sie die absolut frischesten saisonalen Meeresfrüchte erleben und gleichzeitig direkt zur lokalen maritimen Wirtschaft beitragen."
