            2: "Die reiche vulkanische Energie der Insel ist überall spürbar, aber am besten erlebt man sie, indem man die riesigen Resortzentren meidet. Das Zurückziehen in die dampfverhangenen Berggemeinden ermöglicht eine tief entspannende, private Verbindung mit der natürlichen Wärme der Erde."
