            2: "Während die Haupt-Resortmeilen der Hauptinsel riesige Menschenmassen anziehen, gedeiht die wahre maritime Ruhe in der Nähe der ruhigen, verschlafenen Küstendörfer. Das Suchen dieser weniger besuchten Küsten belohnt Sie mit friedlichen Ausblicken, sauberem Wasser und einem langsamen Inselrhythmus, der sich wie eine andere Welt anfühlt."
