      description_1: "Shotrip wird von einem einzigen Ingenieur betrieben. Da wir uns vollständig selbst finanzieren, stehen wir vor großen Herausforderungen durch steigende Kraftstoffkosten und den Zeitaufwand, den Beruf mit der Feldforschung zu vereinbaren.",
