      challenges_section_desc_4: "Wir arbeiten primär eigenfinanziert, um unsere unabhängige Perspektive zu wahren. So bleibt unser Content immer nah an der echten Erfahrung.",
      main_support_section_title: "Shotrip unterstützen",
      main_support_section_desc_1: "Indem Sie uns über",
      main_support_section_desc_2: " unterstützen, helfen Sie uns, Hürden zu überwinden und bessere Inhalte schneller zu liefern.",
      main_support_section_sub_title_1: "Kleine Unterstützung",
      main_support_section_sub_desc_1: "Ein einfacher Weg, zu unseren täglichen Betriebs- und Serverkosten beizutragen. Jede Tasse Kaffee hält die Technik und das Schreiben am Laufen.",
      main_support_section_sub_title_2: "Recherche-Anfrage-Ticket",
      main_support_section_sub_desc_2: "Fordern Sie eine spezifische Region an. Wir besuchen den Ort, sammeln neueste Daten und berichten direkt über den Blog oder YouTube.",
