      closing_section: "Ihre Unterstützung macht aus Interesse Taten. Durch die Finanzierung unserer Reisen ermöglichen Sie es uns, die verborgenen Wahrheiten der japanischen Landschaft zu enthüllen. Danke, dass Sie unsere Erkundung stärken.",
