    about_us: {
      title: "Über uns",
      h1_1: "Reisen in Japan neu definiert",
      h1_2: "Für eine nachhaltige, ",
      h1_3: "authentische Zukunft",
      description: "Shotrip ist ein unabhängiges Medien- und Technologieprojekt, das sich der Lösung des Overtourism verschrieben hat, indem es Reisende mit den unentdeckten Schätzen Japans verbindet.",
      philosophy_section_title: "„Finden Sie Ihre eigenen Favoriten“",
      philosophy_section_desc_1: "In einer Ära viraler Social-Media-Trends werden populäre Orte oft von Massen überrannt. Shotrip fördert einen anderen Ansatz: Orte zu entdecken, die Sie persönlich berühren.",
      philosophy_section_desc_2: "Unsere Mission ist es, Reisenden zu helfen, ein „Dort“ zu finden, das so besonders ist, dass sie ihren engsten Freunden sagen möchten: „Da musst du hin“ – Erlebnisse, die noch lange nach der Reise als geschätzte Erinnerungen bleiben.",
      philosophy_section_side_desc: "Durch die Hervorhebung aller 47 Präfekturen Japans und verborgener Juwelen abseits der „Golden Route“ streben wir an, den Tourismus umzuverteilen und die Ruhe des lokalen Lebens zu bewahren.",
      system_section_title: "Die Technologie",
      system_section_sub_title_1: "Geografische Expertise,",
      system_section_sub_title_2: "übertragen in KI.",
      system_section_desc: "ShotripLens ist ein exklusiver KI-Concierge, entwickelt von einem einzigen Programmierer, der das gesamte Schienennetz und jede Präfektur Japans erkundet hat. Dieses System übersetzt jahrelange geografische Erfahrung und kulturelles Verständnis in einen digitalen Partner, der Sie rund um die Uhr unterstützt.",
      system_section_card: "47 Präfekturen erkundet / Full-Stack-Engineering",
      system_section_commitment_title: "Unsere Verpflichtungen",
      system_section_commitment_sub_title_1: "Privatsphäre zuerst",
      system_section_commitment_desc_1: "Cookie-freier Betrieb. Wir nutzen Technik, um Reisende zu stärken, nicht um sie zu verfolgen.",
      system_section_commitment_sub_title_2: "Lokale Harmonie",
      system_section_commitment_desc_2: "Wahrung des Friedens der Anwohner durch Förderung der Besucherdezentralisierung.",
      future_vision_section_title: "Zukunftsvision",
      future_vision_section_sub_title: "Der Standard für nachhaltiges Reisen werden.",
      future_vision_section_desc: "Shotrip möchte die Lücke zwischen KI, lokalen Behörden und Kreativen schließen, um ein gesünderes Tourismus-Ökosystem zu fördern. Wir bauen mehr als eine Website; wir bauen eine globale Gemeinschaft auf, die Authentizität über Popularität stellt.",
      founder_notes: "„Shotrip ist das Ergebnis meiner lebenslangen Leidenschaft für Japan und meiner Frustration über den Verlust seiner stillen Schönheit. Es ist ein von einer Einzelperson entwickeltes Projekt mit einer besonderen Perspektive, um der Welt das wahre Japan zu zeigen.“",
    },
