      description_1: "Shotrip es mantenido por un solo ingeniero. Al operar totalmente con fondos propios, enfrentamos desafíos significativos por el aumento de los costos de combustible y las limitaciones de tiempo al equilibrar una carrera profesional con la investigación de campo.",
