        "shikoku": {
          name: {
            1: "Itinerari su Fiumi e Vie Navigabili Naturali",
            2: "Incontri Culturali Gestiti dalla Comunità"
          },
          detail: {
            1: "Sperimentate il ritmo dolce e senza fretta dell'isola seguendo i suoi fiumi e canali naturali ben conservati. Andare in canoa o in bicicletta lungo questi percorsi pacifici incarna il viaggio lento, offrendo la massima tranquillità e la totale libertà dalla congestione turistica.",
            2: "Sebbene la regione ospiti festival famosi, la vera magia risiede negli incontri culturali locali che si tengono durante tutto l'anno. Partecipare a questi intimi eventi comunitari permette di sentire il battito autentico e caloroso dell'orgoglio locale in un contesto molto accogliente."
          }
        },
        "kyushu": {
          name: {
            1: "Tavole Calde Locali e Umili",
            2: "Villaggi Termali Isolati tra le Montagne"
          },
          detail: {
            1: "L'incredibile cultura gastronomica di Kyushu si gode al meglio lontano dalle strade commerciali dei ristoranti. Cercare normali tavole calde, tappe locali e bancarelle di cibo tradizionale offre l'accesso a imbattibili sapori regionali a prezzi onesti, completamente liberi dal clamore turistico.",
            2: "La ricca energia vulcanica dell'isola è ovunque, ma il modo migliore per sperimentarla è evitare i grandi centri turistici. Rifugiarsi nelle comunità montane avvolte dal vapore permette una connessione intima, profondamente rilassante e privata con il calore naturale della terra."
          }
        },
        "okinawa": {
          name: {
            1: "Patrimonio Quotidiano dei Villaggi di Ryukyu",
            2: "Fughe Oceaniche nei Villaggi Tranquilli"
          },
          detail: {
            1: "Apprezzate l'identità unica della regione come crocevia culturale esplorando riferimenti storici meno noti e normali villaggi residenziali. Immergersi nella musica locale, nell'artigianato e nella cucina quotidiana lontano dai distretti commerciali offre una connessione ricca e significativa.",
            2: "Mentre le zone dei resort dell'isola principale attirano enormi folle, la vera tranquillità costiera prospera vicino ai villaggi costieri tranquilli e sonnolenti. Cercare queste spiagge meno visitate ripaga con viste pacifiche, acque pulite e un lento ritmo isolano che sembra un mondo a parte."
          }
        },
