      about_founder_3: "หลงใหลในรถไฟท้องถิ่น สถาปัตยกรรม ธรรมชาติ อาหาร และการถ่ายภาพ",
      service_mission: "\"ภารกิจของเราคือการทำให้แน่ใจว่านักเดินทางทุกคนสามารถค้นหา 'สถานที่โปรด' ของตัวเองได้ โดยไม่ต้องหงุดหงิดกับกำแพงภาษาในสถานที่ท่องเที่ยวที่ผู้คนไม่แออัด\"",
      about_japan: "ยินดีต้อนรับสู่ญี่ปุ่น",
      about_japan_detail: "ญี่ปุ่นเป็นประเทศเกาะในเอเชียตะวันออก มีชื่อเสียงในด้านการผสมผสานที่เป็นเอกลักษณ์ระหว่างประเพณีโบราณและเทคโนโลยีล้ำสมัย ตั้งแต่ทิวทัศน์เมืองที่คึกคักไปจนถึงธรรมชาติอันเงียบสงบ มีมุมมองที่หลากหลายของญี่ปุ่นที่กำลังรอนักเดินทางทุกคนมาค้นหา",
