        kansai: "มนต์เสน่ห์อันลึกซึ้งที่สุดของคันไซจะถูกค้นพบเมื่อคุณเดินทางออกจากศูนย์กลางเมืองที่เร่งรีบและสถานที่ท่องเที่ยวทางประวัติศาสตร์ที่หนาแน่น การมุ่งหน้าเข้าสู่เทือกเขาอันศักดิ์สิทธิ์ที่ปกคลุมด้วยสายหมอกและหมู่บ้านชนบทอันเงียบสงบ จะช่วยเปิดประตูสู่จิตวิญญาณอันเก่าแก่และเหนือกาลเวลาของเอกลักษณ์ทางความเชื่อของญี่ปุ่นท่ามกลางความสงบอย่างสมบูรณ์",
        chugoku: "ชูโกคุมอบการเดินทางอันเงียบสงบและงดงามผ่านภูมิประเทศที่เต็มไปด้วยตำนานและชายฝั่งที่เงียบสงบ ความลับของภูมิภาคนี้คือการสำรวจให้เลยเมืองหน้าด่านหลักๆ เพื่อค้นหาทิวทัศน์ทะเลในอันเงียบสงบ ศาลเจ้าบนเขาอันเงียบเชียบ และย่านคลองประวัติศาสตร์ที่ยังคงรักษาความดั้งเดิมไว้ได้อย่างงดงาม",
        shikoku: "ชิโกคุคือจุดหมายปลายทางชั้นนำของญี่ปุ่นสำหรับการท่องเที่ยวแบบสโลว์ทราเวล และเป็นเหมือนลมหายใจอันสดชื่นสำหรับจิตวิญญาณ ด้วยเสน่ห์ของชนบทที่โอบล้อมไปทั้งเกาะ แม่น้ำสีมรกต และชายฝั่งที่อ่อนโยน ที่นี่มอบจังหวะชีวิตที่ดำเนินไปอย่างไม่เร่งรีบและหาได้ยาก ซึ่งคุณสามารถดื่มด่ำกับวัฒนธรรมท้องถิ่นได้อย่างเต็มที่โดยไม่มีสิ่งรบกวนใดๆ",
        kyushu: "คิวชูคือเกาะอันทรงพลังที่เต็มไปด้วยพลังงานจากภูเขาไฟและประวัติศาสตร์อันรุ่งเรือง พร้อมทั้งความอบอุ่นของผู้คนในท้องถิ่น เพื่อสัมผัสจิตวิญญาณที่แท้จริง จงหลีกเลี่ยงเมกะรีสอร์ตเชิงพาณิชย์ และออกตามหาหมู่บ้านน้ำพุร้อนลึกลับในหุบเขา รวมถึงวัฒนธรรมอาหารตามตรอกซอกซอยที่เปี่ยมด้วยจิตวิญญาณ ซึ่งเป็นสิ่งนิยามภูมิภาคอันมีชีวิตชีวาแห่งนี้",
