      body_1: "Vượt khuôn khổ của những cuốn sách hướng dẫn và khám phá những viên ngọc ẩn giấu mang đậm dấu ấn cá nhân của bạn. Là một kỹ sư CNTT kiêm dịch giả chuyên nghiệp đã đi qua tất cả 47 tỉnh thành Nhật Bản, tôi thành lập Shotrip nhằm xóa bỏ rào cản ngôn ngữ và giúp bạn trải nghiệm một Nhật Bản chân thực nhất.",
