        tohoku: "Vùng đất của những lễ hội vượt thời gian, những suối nước nóng mộc mạc và phong cảnh ngoạn mục qua sáu tỉnh phía bắc độc đáo.",
        kanto: "Trái tim của Nhật Bản, nơi năng lượng đèn neon của Tokyo gặp gỡ các ngôi đền lịch sử và các điểm nghỉ dưỡng ven biển đa dạng.",
        hokuriku: "Giàu nghề thủ công truyền thống và lịch sử samurai, mang đến tầm nhìn tuyệt đẹp ra Biển Nhật Bản cùng các món ngon theo mùa.",
        chubu: "Nơi có núi Phú Sĩ hùng vĩ, dãy Alps Nhật Bản và sự kết hợp hấp dẫn giữa sức mạnh công nghiệp cùng nét quyến rũ cổ xưa.",
        kansai: "Linh hồn văn hóa của Nhật Bản, nổi bật với những kỳ quan cổ kính của Kyoto, Nara và văn hóa ẩm thực sôi động của Osaka.",
        chugoku: "Một vùng đất mang vẻ đẹp thanh bình, từ những ngôi đền nổi biểu tượng của Miyajima đến những cồn cát độc đáo của Tottori.",
        shikoku: "Một hòn đảo thanh bình nổi tiếng với hành trình hành hương qua 88 ngôi đền, những thung lũng ẩn giấu và Biển nội địa Seto nổi tiếng thế giới.",
        kyushu: "Hòn đảo núi lửa đầy nhiệt huyết, nổi tiếng với những bát ramen tuyệt hảo, các thị trấn suối nước nóng tươi tốt và các thành phố cảng lịch sử.",
        okinawa: "Thiên đường nhiệt đới của Nhật Bản, sở hữu làn nước trong xanh như ngọc bích, di sản Ryukyu độc đáo và bầu không khí đảo thư thái."
