        chugoku: "Chugoku mang lại một hành trình yên bình tuyệt đẹp qua các cảnh quan giàu thần thoại và bờ biển thanh bình. Bí mật của vùng này là khám phá qua các thành phố cửa ngõ chính để tìm thấy tầm nhìn ra biển nội địa yên bình, các đền thờ núi lặng lẽ và các khu phố kênh đào lịch sử vẫn giữ được bản sắc nguyên bản với cội nguồn của chúng.",
        shikoku: "Shikoku là điểm đến hàng đầu của Nhật Bản cho phong cách du lịch chậm (slow travel) và là một làn gió trong lành cho tâm hồn. Được ban phước với toàn bộ một hòn đảo mang nét duyên dáng nông thôn, các dòng sông màu ngọc bích và bờ biển dịu dàng, nơi đây mang lại một nhịp sống thư thái, hiếm có, nơi bạn có thể đắm mình hoàn toàn vào văn hóa địa phương mà không có bất kỳ sự xao nhãng nào.",
        kyushu: "Kyushu là một hòn đảo năng động của năng lượng núi lửa và lịch sử phong phú, tràn ngập sự ấm áp của người dân địa phương. Để trải nghiệm tinh thần thực sự của nó, hãy bỏ qua các siêu nghỉ dưỡng thương mại hóa và tìm kiếm các bản làng suối nước nóng ẩn mình trong núi và văn hóa ẩm thực khu phố đầy tâm hồn định hình nên vùng đất sôi động này.",
        okinawa: "Thiên đường cận nhiệt đới của Okinawa được trải nghiệm tốt nhất bằng cách đón nhận nhịp điệu địa phương chậm hơn. Trong khi các dải resort chính thu hút đám đông, thì tinh thần Ryukyu đích thực và làn nước trong xanh như ngọc nguyên sơ lại phát triển mạnh mẽ trên các hòn đảo nhỏ bên ngoài, mang lại những bãi biển cát trắng vắng người và sự yên bình tối cao."
